#!/usr/bin/env python3
"""Relay between the QEMU serial port (TCP) and a telnet client on 127.0.0.1:6665.

On each client connection it replays the tail of the guest output and pokes the
guest with a carriage return so the login prompt is shown immediately.
"""
import socket
import threading
import select
import sys

GUEST_PORT = 7000
CLIENT_PORT = 6665
LOGFILE = "/tmp/boot.log"

IAC, DONT, DO, WONT, WILL, SB, SE = 255, 254, 253, 252, 251, 250, 240
ECHO, SGA = 1, 3

buf = bytearray()
buf_lock = threading.Lock()
guest = {"sock": None}
client = {"sock": None}


def strip_telnet(data, state):
    """Remove telnet IAC sequences from client input; returns (clean, replies)."""
    out = bytearray()
    replies = bytearray()
    for b in data:
        if state["mode"] == "data":
            if b == IAC:
                state["mode"] = "iac"
            else:
                out.append(b)
        elif state["mode"] == "iac":
            if b == IAC:
                out.append(IAC)
                state["mode"] = "data"
            elif b in (DO, DONT, WILL, WONT):
                state["mode"] = "opt"
                state["cmd"] = b
            elif b == SB:
                state["mode"] = "sb"
            else:
                state["mode"] = "data"
        elif state["mode"] == "opt":
            cmd = state["cmd"]
            if cmd == DO:
                replies += bytes([IAC, WILL if b in (ECHO, SGA) else WONT, b])
            elif cmd == WILL:
                replies += bytes([IAC, DONT if b not in (SGA,) else DO, b])
            state["mode"] = "data"
        elif state["mode"] == "sb":
            if b == SE:
                state["mode"] = "data"
    return bytes(out), bytes(replies)


def guest_reader():
    log = open(LOGFILE, "ab", buffering=0)
    while True:
        s = guest["sock"]
        if s is None:
            return
        try:
            data = s.recv(4096)
        except OSError:
            data = b""
        if not data:
            return
        log.write(data)
        with buf_lock:
            buf.extend(data)
            del buf[:-8192]
        c = client["sock"]
        if c is not None:
            try:
                c.sendall(data)
            except OSError:
                pass


def serve_clients(lsock):
    while True:
        c, _ = lsock.accept()
        old = client["sock"]
        if old is not None:
            try:
                old.shutdown(socket.SHUT_RDWR)
            except OSError:
                pass
        c.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)
        client["sock"] = c
        threading.Thread(target=handle_client, args=(c,), daemon=True).start()


def handle_client(c):
    state = {"mode": "data", "cmd": 0}
    try:
        # put the telnet client into character-at-a-time mode
        c.sendall(bytes([IAC, WILL, ECHO, IAC, WILL, SGA]))
        with buf_lock:
            tail = bytes(buf[-2048:])
        if tail:
            c.sendall(tail)
        g = guest["sock"]
        if g is not None:
            g.sendall(b"\r")
        while True:
            r, _, _ = select.select([c], [], [], 60)
            if not r:
                continue
            data = c.recv(4096)
            if not data:
                break
            clean, replies = strip_telnet(data, state)
            if replies:
                c.sendall(replies)
            g = guest["sock"]
            if clean and g is not None:
                g.sendall(clean)
    except OSError:
        pass
    finally:
        if client["sock"] is c:
            client["sock"] = None
        try:
            c.close()
        except OSError:
            pass


def main():
    gl = socket.socket()
    gl.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    gl.bind(("127.0.0.1", GUEST_PORT))
    gl.listen(1)

    cl = socket.socket()
    cl.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    cl.bind(("127.0.0.1", CLIENT_PORT))
    cl.listen(5)

    threading.Thread(target=serve_clients, args=(cl,), daemon=True).start()
    sys.stderr.write("relay listening: guest %d, telnet %d\n" % (GUEST_PORT, CLIENT_PORT))
    sys.stderr.flush()

    while True:
        g, _ = gl.accept()
        g.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)
        guest["sock"] = g
        guest_reader()
        guest["sock"] = None
        try:
            g.close()
        except OSError:
            pass


if __name__ == "__main__":
    main()

